'use client';

import type { Easing, Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef, useId } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface Layers01IconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface Layers01IconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const TOP =
  'M8.64298 3.14559L6.93816 3.93362C4.31272 5.14719 3 5.75397 3 6.75C3 7.74603 4.31272 8.35281 6.93817 9.56638L8.64298 10.3544C10.2952 11.1181 11.1214 11.5 12 11.5C12.8786 11.5 13.7048 11.1181 15.357 10.3544L17.0618 9.56638C19.6873 8.35281 21 7.74603 21 6.75C21 5.75397 19.6873 5.14719 17.0618 3.93362L15.357 3.14559C13.7048 2.38186 12.8786 2 12 2C11.1214 2 10.2952 2.38186 8.64298 3.14559Z';
const MIDDLE =
  'M20.788 11.0972C20.9293 11.2959 21 11.5031 21 11.7309C21 12.7127 19.6873 13.3109 17.0618 14.5072L15.357 15.284C13.7048 16.0368 12.8786 16.4133 12 16.4133C11.1214 16.4133 10.2952 16.0368 8.64298 15.284L6.93817 14.5072C4.31272 13.3109 3 12.7127 3 11.7309C3 11.5031 3.07067 11.2959 3.212 11.0972';
const BOTTOM =
  'M20.3767 16.2661C20.7922 16.5971 21 16.927 21 17.3176C21 18.2995 19.6873 18.8976 17.0618 20.0939L15.357 20.8707C13.7048 21.6236 12.8786 22 12 22C11.1214 22 10.2952 21.6236 8.64298 20.8707L6.93817 20.0939C4.31272 18.8976 3 18.2995 3 17.3176C3 16.927 3.20778 16.5971 3.62334 16.2661';

// A new sheet falls in from the top like a solid sheet (a mask that moves
// with it hides whatever it covers) and, on landing, pushes the stack down one
// slot: the old top sheet becomes the middle layer (a clip trims it to the
// middle-layer shape), the middle sheet becomes the bottom one, and the bottom
// sheet slides out. The stack then bounces like jelly. At the end each sheet
// sits on a rest shape, so the swap back to rest is invisible.
const LAYER_DURATION = 1.15;
const LAYER_TIMES = [0, 0.26, 0.42, 0.56, 0.7, 0.84, 0.999, 1];
const LAYER_EASE: Easing[] = [
  'easeIn',
  [0.23, 1, 0.32, 1],
  'easeInOut',
  'easeInOut',
  'easeInOut',
  'linear',
  'linear',
];
const DROP_FROM = -13;
const SLOT = 4.95;
// Damped bounce after the push lands.
const BOUNCE = [1.2, -0.45, 0.18, 0];
const settle = (base: number, k = 1) => BOUNCE.map((o) => base + o * k);

// The clip's top edge follows the falling sheet, then stays 5.75 below the
// old top sheet's own origin, which is where the middle layer's ends sit.
const CLIP_BOTTOM = 70;
const CLIP_HEIGHT = 110;
const CLIP_REST_TOP = CLIP_BOTTOM - CLIP_HEIGHT;
const CLIP_TOPS = [-0.35, 6.49, ...settle(SLOT + 5.75), 10.7, CLIP_REST_TOP];

const newSheetVariants: Variants = {
  normal: { translateY: DROP_FROM },
  animate: {
    translateY: [DROP_FROM, -SLOT, ...settle(0), 0, DROP_FROM],
    transition: { duration: LAYER_DURATION, ease: LAYER_EASE, times: LAYER_TIMES },
  },
};

const topVariants: Variants = {
  normal: { translateY: 0 },
  animate: {
    translateY: [0, 0, ...settle(SLOT), SLOT, 0],
    transition: { duration: LAYER_DURATION, ease: LAYER_EASE, times: LAYER_TIMES },
  },
};

const clipVariants: Variants = {
  normal: { attrY: CLIP_REST_TOP, height: CLIP_HEIGHT },
  animate: {
    attrY: CLIP_TOPS,
    height: CLIP_TOPS.map((top) => CLIP_BOTTOM - top),
    transition: { duration: LAYER_DURATION, ease: LAYER_EASE, times: LAYER_TIMES },
  },
};

const middleVariants: Variants = {
  normal: { d: MIDDLE, translateY: 0 },
  animate: {
    d: [MIDDLE, MIDDLE, BOTTOM, BOTTOM, BOTTOM, BOTTOM, BOTTOM, MIDDLE],
    translateY: [0, 0, ...settle(0, 0.7), 0, 0],
    transition: { duration: LAYER_DURATION, ease: LAYER_EASE, times: LAYER_TIMES },
  },
};

const bottomVariants: Variants = {
  normal: { translateY: 0 },
  animate: {
    translateY: [0, 0, 9, 9, 9, 9, 9, 0],
    transition: { duration: LAYER_DURATION, ease: LAYER_EASE, times: LAYER_TIMES },
  },
};

const generatedGeometryVariants: Variants = {
  normal: { visibility: 'hidden', transition: { duration: 0 } },
  animate: {
    visibility: ['visible', 'visible', 'hidden'],
    transition: { duration: LAYER_DURATION, times: [0, 0.999, 1] },
  },
};

const Layers01Icon = forwardRef<Layers01IconHandle, Layers01IconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const maskId = useId();
    const clipId = useId();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: false,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="hidden"
        >
          <defs>
            <mask id={maskId} maskUnits="userSpaceOnUse" x="-5" y="-20" width="34" height="50">
              <rect x="-5" y="-20" width="34" height="50" fill="white" />
              <motion.path
                d={TOP}
                fill="black"
                stroke="black"
                strokeWidth="3.5"
                strokeLinejoin="round"
                variants={newSheetVariants}
                animate={controls}
                initial="normal"
              />
            </mask>
            <clipPath id={clipId} clipPathUnits="userSpaceOnUse">
              <motion.rect
                x="-5"
                y={CLIP_REST_TOP}
                width="34"
                height={CLIP_HEIGHT}
                variants={clipVariants}
                animate={controls}
                initial="normal"
              />
            </clipPath>
          </defs>
          <g mask={`url(#${maskId})`} clipPath={`url(#${clipId})`}>
            <motion.path
              d={TOP}
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={topVariants}
              animate={controls}
              initial="normal"
            />
          </g>
          <motion.path
            d={MIDDLE}
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
            variants={middleVariants}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d={BOTTOM}
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
            variants={bottomVariants}
            animate={controls}
            initial="normal"
          />
          <motion.g
            variants={generatedGeometryVariants}
            animate={controls}
            initial="normal"
          >
            <motion.path
              d={TOP}
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={newSheetVariants}
              animate={controls}
              initial="normal"
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);

Layers01Icon.displayName = 'Layers01Icon';

export { Layers01Icon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { spring, useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

/**
 * A damped spring as the easing of one keyframe segment: the value overshoots
 * its target and settles on it. Use it for landings so every icon shares the
 * same physical bounce. Higher `bounce` gives more oscillation.
 */
export function springEase(bounce = 0.45, visualDuration = 0.35) {
  const generator = spring({ keyframes: [0, 1], bounce, visualDuration });
  let settle = 0;
  while (!generator.next(settle).done && settle < 5000) settle += 10;
  return (progress: number) =>
    progress >= 1 ? 1 : generator.next(progress * settle).value;
}

const NUMBER = /-?\d*\.?\d+/g;

/**
 * The path at position `t` along a row of poses that share the same path
 * commands: `t = 1` is the second pose, `t = 1.5` is halfway to the third.
 * Waves use it to move along their own curvature instead of scaling, so the
 * stroke keeps its width.
 */
export function pathAt(poses: string[], t: number) {
  const i = Math.min(Math.max(Math.floor(t), 0), poses.length - 2);
  const to = poses[i + 1].match(NUMBER) ?? [];
  let k = 0;
  return poses[i].replace(NUMBER, (from) => {
    const value = Number(from) + (Number(to[k++]) - Number(from)) * (t - i);
    return String(Math.round(value * 10000) / 10000);
  });
}

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
